// ===== GoEdge WAF 人机验证(qmzw5/123wxwz) =====
var MOBILE_UA = 'Mozilla/5.0 (Linux; Android 15; 23113RKC6C Build/AQ3A.240912.001; wv) AppleWebKit/537.36 (KHTML, like Gecko) Version/4.0 Chrome/142.0.0.0 Mobile Safari/537.36';

function goedgeVerify(serverUrl, html) {
  const {java} = this;
  // 从GoEdge挑战页提取CAPTCHA_ID与验证码图地址→弹窗输码→提交表单。通过返回true
  var cid = (String(html).match(/name="GOEDGE_WAF_CAPTCHA_ID" value="([^"]+)"/) || [])[1];
  var img = (String(html).match(/src="(\/WAF\/VERIFY\/CAPTCHA[^"]+)"/) || [])[1];
  if (!cid || !img) return false;
  var code = '';
  try { code = String(java.getVerificationCode(serverUrl + img) || '').trim(); } catch (e) { return false; }
  if (!code) return false;
  var postUrl = serverUrl + '/index.php?action=loadChapterPage';
  var vBody = 'GOEDGE_WAF_CAPTCHA_ID=' + encodeURIComponent(cid) + '&GOEDGE_WAF_CAPTCHA_CODE=' + encodeURIComponent(code);
  var vResp = '';
  for (var rt = 0; rt < 3; rt++) {
    vResp = String(java.ajax(postUrl + ',' + JSON.stringify({
      body: vBody, method: 'POST',
      headers: JSON.stringify({'user-agent': MOBILE_UA, 'Referer': postUrl, 'Content-Type': 'application/x-www-form-urlencoded'})
    })));
    if (!/javax\.net\.ssl|Exception|reset by peer|Failed to connect/i.test(vResp)) break;
    if (rt < 2) Packages.java.lang.Thread.sleep(600);
  }
  java.log('WAF验证提交: ' + (/GOEDGE_WAF_CAPTCHA/.test(vResp) ? '仍被挑战' : '已放行'));
  return !/GOEDGE_WAF_CAPTCHA/.test(vResp);
}

function rebuildTocKey(serverUrl, bookId) {
  // 重新抓书籍页提取最新AES密钥(qmzw5/123wxwz的密钥JS为随机文件名且内容定期轮换)
  const {java, cache} = this;
  try {
    var dh = '';
    for (var rt = 0; rt < 3; rt++) {
      // 时间戳参数强制CDN回源: 缓存版HTML引用的是已过期的随机名密钥JS, 是业务Error的根因
      dh = String(java.ajax(serverUrl + '/book/' + bookId + '.html?_=' + Date.now() + ',' + JSON.stringify({headers: JSON.stringify({'user-agent': MOBILE_UA})})));
      if (!/javax\.net\.ssl|Exception|reset by peer|Failed to connect/i.test(dh)) break;
      if (rt < 2) Packages.java.lang.Thread.sleep(500);
    }
    if (/GOEDGE_WAF_CAPTCHA_ID/.test(dh)) {
      java.toast('站点人机验证，请在弹窗中输入验证码');
      if (!goedgeVerify(serverUrl, dh)) return false;
      dh = String(java.ajax(serverUrl + '/book/' + bookId + '.html?_=' + Date.now() + ',' + JSON.stringify({headers: JSON.stringify({'user-agent': MOBILE_UA})})));
    }
    var kre = /src="(\/templates\/js\/[a-zA-Z0-9]{10,}\.js)"/g, km;
    while ((km = kre.exec(dh)) !== null) {
      var rj = '';
      for (var rt2 = 0; rt2 < 3; rt2++) {
        rj = String(java.ajax(serverUrl + km[1] + ',' + JSON.stringify({headers: JSON.stringify({'user-agent': MOBILE_UA})})));
        if (!/javax\.net\.ssl|Exception|reset by peer|Failed to connect/i.test(rj)) break;
        if (rt2 < 2) Packages.java.lang.Thread.sleep(400);
      }
      var sk = (rj.match(/AESCrypt\('(.*?)'\)/) || [])[1];
      var ik = (rj.match(/parse\('(.*?)'\)/) || [])[1];
      if (sk && ik) { cache.put(serverUrl, JSON.stringify({ secretKey: sk, ivKey: ik })); java.log('密钥重建成功: ' + km[1]); return true; }
    }
  } catch (e) { java.log('密钥重建异常: ' + e); }
  return false;
}

// ===== 加解密函数 =====
function textEncrypt(text) {
    let passwd = "lzxHpH8PLGXcrCIQ";
    let key = passwd.padEnd(32, "\\0");
    let iv = passwd.padEnd(16, "\\0");

    let cipher = this.java.createSymmetricCrypto(
            "aes/cbc/pkcs7padding",
            key,
            iv
        )
        .encryptBase64(text);

    return encodeURIComponent(cipher);
}

function dataEncrypt(body, srv) {
    const {java, cache} = this;

    var ck = srv || GET.call(this, 'server');
    let keys = cache.get(ck);
    if (!keys || keys == 'null') {
      var alt = ck.indexOf('https:') === 0 ? ('http:' + ck.substring(5)) : ('https:' + ck.substring(4));
      keys = cache.get(alt) || keys;
    }

    let data = {};
